const candidates = ($input.first().json.email_contacts || []).filter(c => c.verification === 'VERIFIED_HIGH');
const classified = candidates.map(c => {
  const hasForm = (c.why || '').toLowerCase().includes('form');
  const hasBooking = (c.why || '').toLowerCase().includes('booking');
  const hasCalculator = (c.why || '').toLowerCase().includes('calculator');
  let classification = 'F';
  if (hasForm) classification = 'C';
  if (hasBooking) classification = 'D';
  if (hasCalculator) classification = 'C';
  return { json: { ...c, classification, opportunity_type: classification === 'F' ? 'reject/deprioritize' : classification === 'C' ? 'quote/qualification calculator' : classification === 'D' ? 'booking automation' : 'CRO/lead-flow improvement' } };
});
return classified;
